const inlineRules = [
 { re: /^(\d+) rec$/, en: (m) => m[1] + ' bed' },
 { re: /^(\d+(?:\.\d+)?) baños$/, en: (m) => m[1] + ' bath' },
 { re: /^(\d+) est$/, en: (m) => m[1] + ' park' },
 { re: /^(\d+) cajones$/, en: (m) => m[1] + ' spots' },
 { re: /^Precio mensual · (.+)$/, en: (m) => 'Monthly price · ' + (translations[m[1]] || m[1]) },
 { re: /^Precio de venta · (.+)$/, en: (m) => 'Sale price · ' + (translations[m[1]] || m[1]) },
 { re: /^(\$[\d,]+)\/mes$/, en: (m) => m[1] + '/mo' },
];

export { translations, inlineRules };
